struct Rectangle
{
    double width{};
    double height{};
};

double area(const Rectangle& r)
{
    return r.width * r.height;
}

void scale(Rectangle& r, double factor)
{
    r.width *= factor;
    r.height *= factor;
}

unitTests:
TEST("area") { CHECK_NEAR(area(Rectangle{ 3.0, 4.0 }), 12.0, 1e-12); }
TEST("scale changes the caller's rectangle") { Rectangle r{ 2.0, 5.0 }; scale(r, 3.0); CHECK_NEAR(r.width, 6.0, 1e-12); CHECK_NEAR(r.height, 15.0, 1e-12); }
TEST("scaling by 2 makes the area 4 times bigger") { Rectangle r{ 1.5, 2.0 }; const double before{ area(r) }; scale(r, 2.0); CHECK_NEAR(area(r), before * 4, 1e-9); }

